    ('ChIJMQcHrMUEdkgRCvMbPS0cuss', 'The Red Lion, Parliament Street', '48 Parliament St, London SW1A 2NH, UK', 51.50207770, -0.12573250, 'PUB', null, '020 7930 5826', 4.1, 5713, 'places/ChIJMQcHrMUEdkgRCvMbPS0cuss/photos/Aa-ngMZ07rs86puBufdZC7acYZf85BKdrwZge3u59MMkaaURxWdhkEqjUevAutG1CALP4A45bsiUxoxy6uPNryB8K859btFT8yweWNWW0G4-_oqNXLcw5j4Bp_6z9HQ20bDT6hbEre9GLRf4-65b-VUMFnpBrw3O6GsXk5d1XC_V3mOQD_4q1JE53rG-5ltI0-vx58lE3VexT9k4zFAYunFzRvrUYcBZRIgBE0Wyay4nMDo9MN4LTE-cJobHa5CijT677BsEuv5H-jTdvinXtGuPySQT49buQ9owlMIG2IDHUPfftuQ9KBIQVR6B6W25Q683IEK5eAmfDjbnY6mFCBScj5Y-1wPC79fbywGKhCV2Rxp_ufvLm5ZZTZBFUkUCdfOC7kCmvnEa_1wUaetdWZBcKAP9wYM', 'OPERATIONAL'),
    -- 원본 101행: Waxy O'Connor's / https://maps.app.goo.gl/Cdyn52JQbFwnrooG6
    ('ChIJI_raytMEdkgRQBNj5weKsxM', 'Waxy O''Connor''s', '14-16 Rupert St, London W1D 6DD, UK', 51.51083200, -0.13233600, 'PUB', null, '020 7287 0255', 4.5, 9821, 'places/ChIJI_raytMEdkgRQBNj5weKsxM/photos/Aa-ngMbzllkG3S8R9PmOzMQEFGc6HXpNwOmjQ_1OhPzckzQ_LzHAg9EFqvncyH-91NqgHvrgf4d9WhW9yp5uGTT0YIMW7jzyrN6yH8qLWCENA_vNpC9pHePfCeJx29dno3LLpmcolAzRmAdlcmkr2FC5drEQ6Xc_s4pqGsU4IGQWmwklUYht9YzugNFe9vnpgg4XjUhT8stuEPhW1Yj8WwfLOHp1cTlQIb8endYT2X97Llrsnnk5DS852swIb53eVNnty9GvDN_GJLr3ahsdlM0xugUzQ11fqOsthxL0yim9umIzr3HHgTFeZbBorebIV5eNBQ0--cem6nlVgtBwWtAvml1mzFMwts2qP7hUIkP7BnJkCg0FgXffXR7ikO8LkAt6jMYo5zir6s5KvLv8dIaln-h13g', 'OPERATIONAL')
        ) as source (
            google_place_id, name, address, latitude, longitude, category, secondary_category,
            phone_number, rating, review_count, photo_reference, business_status
        )
    loop
        insert into public.place_cache (
            google_place_id, name, address, latitude, longitude, category,
            phone_number, rating, review_count, photo_reference, business_status
        ) values (
            seed.google_place_id, seed.name, seed.address, seed.latitude, seed.longitude, seed.category,
            seed.phone_number, seed.rating, seed.review_count, seed.photo_reference, seed.business_status
        )
        on conflict (google_place_id) do update set
            name = excluded.name,
            address = excluded.address,
            latitude = excluded.latitude,
            longitude = excluded.longitude,
            category = excluded.category,
            phone_number = excluded.phone_number,
            rating = excluded.rating,
            review_count = excluded.review_count,
            photo_reference = excluded.photo_reference,
            business_status = excluded.business_status
        returning id into saved_place_id;

        insert into public.solo_dining_place (place_id)
        values (saved_place_id)
        on conflict (place_id) do nothing;

        delete from public.place_category where place_id = saved_place_id;
        insert into public.place_category (place_id, category, category_order)
        values (saved_place_id, seed.category, 0);
        registered_categories := registered_categories + 1;

        if seed.secondary_category is not null then
            insert into public.place_category (place_id, category, category_order)
            values (saved_place_id, seed.secondary_category, 1);
            registered_categories := registered_categories + 1;
        end if;
        registered_places := registered_places + 1;
    end loop;

    if registered_places <> 98 or registered_categories <> 107 then
        raise exception 'Unexpected seed counts: places %, categories %', registered_places, registered_categories;
    end if;
end;
$london_seed$;


