select count(distinct p.id) as registered_place_count,
       count(c.place_id) as registered_category_count,
       count(*) filter(where c.category = 'RESTAURANT') as restaurant_count,
       count(*) filter(where c.category = 'CAFE') as cafe_count,
       count(*) filter(where c.category = 'PUB') as pub_count,
       count(*) filter(where c.category = 'DESSERT') as dessert_count
from expected e join public.place_cache p on p.google_place_id = e.google_place_id
left join public.place_category c on c.place_id = p.id;
